create function public.search_budget()returns void language plpgsql security definer set search_path=''as $$begin if not private.member()then raise insufficient_privilege;end if;perform private.rate_limit('scholarly_search',10);end$$;
revoke all on function public.search_budget()from public,anon;grant execute on function public.search_budget()to authenticated;
create function public.scholarly_cache_get(key text)returns jsonb language sql security invoker set search_path=''as $$select response from private.scholarly_cache where cache_key=key and expires_at>now()$$;
create function public.scholarly_cache_put(key text,value jsonb)returns void language sql security invoker set search_path=''as $$insert into private.scholarly_cache values(key,value,now()+interval '1 day')on conflict(cache_key)do update set response=excluded.response,expires_at=excluded.expires_at$$;
revoke all on function public.scholarly_cache_get(text),public.scholarly_cache_put(text,jsonb)from public,anon,authenticated;
grant usage on schema private to service_role;grant select,insert,update,delete on private.scholarly_cache to service_role;
grant execute on function public.scholarly_cache_get(text),public.scholarly_cache_put(text,jsonb)to service_role;
grant select,insert,update on public.papers to service_role;
create function public.search_community(search_text text)returns jsonb language sql stable security invoker set search_path=''as $$select jsonb_build_object(
'posts',(select coalesce(jsonb_agg(x),'[]')from(select *from public.posts where length(search_text)between 2 and 200 and to_tsvector('english',title||' '||body||' '||array_to_string(tags,' '))@@websearch_to_tsquery('english',search_text)order by created_at desc,id desc limit 30)x),
'profiles',(select coalesce(jsonb_agg(x),'[]')from(select *from public.profiles where length(search_text)between 2 and 200 and to_tsvector('english',name||' '||methods||' '||equipment||' '||array_to_string(interests,' '))@@websearch_to_tsquery('english',search_text)order by id limit 30)x),
'projects',(select coalesce(jsonb_agg(x),'[]')from(select *from public.projects where length(search_text)between 2 and 200 and to_tsvector('english',title||' '||problem||' '||methods||' '||needs||' '||equipment)@@websearch_to_tsquery('english',search_text)order by created_at desc,id desc limit 30)x))$$;
revoke all on function public.search_community(text)from public;grant execute on function public.search_community(text)to authenticated,anon;
-- Recommendation candidate window is cursor-bounded first; hard RLS constraints remain outside scores.
create function public.recommended_page(before_time timestamptz default null,before_id uuid default null)returns jsonb language sql stable security invoker set search_path=''as $$with candidates as(select p.*from public.posts p where p.state='published'and(before_time is null or(p.created_at,p.id)<(before_time,before_id))and not exists(select 1 from public.preferences f where f.user_id=auth.uid()and p.tags&&f.muted)order by created_at desc,id desc limit 30),scores as(select p.id,4*(select count(*)from unnest(p.tags)t where t=any(coalesce((select interests from public.preferences where user_id=auth.uid()),(select interests from public.profiles where id=auth.uid()),'{}')))+2*exp(-greatest(0,extract(epoch from(now()-p.created_at)))/604800)+case when p.source_url<>''then 1 else 0 end+case when p.methods<>''then 0.5 else 0 end+case when p.resolution<>''then 1.5 else 0 end score from candidates p)select coalesce(jsonb_agg(jsonb_build_object('post',p,'score',s.score,'reason','Interest overlap, seven-day freshness decay and methods/source/resolution quality. No grades or raw reactions.')order by s.score desc,p.id),'[]')from candidates p join scores s on s.id=p.id$$;
revoke all on function public.recommended_page(timestamptz,uuid)from public;grant execute on function public.recommended_page(timestamptz,uuid)to authenticated,anon;
